ALTER TABLE "arth_command_outbox" ADD CONSTRAINT "arth_command_outbox_kind" CHECK ("arth_command_outbox"."kind" IN ('customer_restriction', 'workspace_ownership_transfer', 'model_routing_control', 'platform_integration_control', 'platform_adapter_release_control'));--> statement-breakpoint
ALTER TABLE "arth_command_outbox" ADD CONSTRAINT "arth_command_outbox_payload_identity" CHECK ("arth_command_outbox"."payload"->>'kind' = "arth_command_outbox"."kind"::text AND "arth_command_outbox"."payload"->>'revisionNumber' ~ '^[1-9][0-9]*$' AND ("arth_command_outbox"."payload"->>'revisionNumber')::integer = "arth_command_outbox"."aggregate_revision" AND (("arth_command_outbox"."kind" = 'customer_restriction' AND "arth_command_outbox"."payload"->>'restrictionId' = "arth_command_outbox"."aggregate_id"::text) OR ("arth_command_outbox"."kind" = 'workspace_ownership_transfer' AND "arth_command_outbox"."payload"->>'transferId' = "arth_command_outbox"."aggregate_id"::text) OR ("arth_command_outbox"."kind" = 'model_routing_control' AND "arth_command_outbox"."payload"->>'controlId' = "arth_command_outbox"."aggregate_id"::text) OR ("arth_command_outbox"."kind" = 'platform_integration_control' AND "arth_command_outbox"."payload"->>'integrationId' = "arth_command_outbox"."aggregate_id"::text) OR ("arth_command_outbox"."kind" = 'platform_adapter_release_control' AND "arth_command_outbox"."payload"->>'releaseId' = "arth_command_outbox"."aggregate_id"::text)));
